/**
 * FX.4 — AI semantic-match for flagged enum cells, layered on the pure
 * coercion engine (flat-file-coerce.ts).
 *
 * When a mapped external value doesn't match any of the column's options by
 * exact/normalized text (e.g. supplier "rosso" / "impermeabile" vs the column's
 * "Red" / "Waterproof"), this asks the model to pick the single best option —
 * CONSTRAINED to the option list so it can't hallucinate a value Amazon would
 * reject. Mirrors the proven constrained-prompt approach in
 * value-translate.service.ts, but takes the options directly (no DB / no
 * cross-market schema load) and runs one call per enum column.
 *
 * Graceful: with the AI kill-switch on or no provider configured, every value
 * resolves to null (the cell stays flagged for manual fixing) — never throws.
 */

import { getProvider, isAiKillSwitchOn } from '../ai/providers/index.js'
import { logUsage } from '../ai/usage-logger.service.js'
import { coerceRows, type CoercibleColumnWithId, type CoerceRowsResult } from './flat-file-coerce.js'

function parseJsonObject(text: string): Record<string, unknown> {
  let c = text.trim()
  if (c.startsWith('```')) c = c.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '')
  const brace = c.indexOf('{')
  if (brace > 0) c = c.slice(brace)
  try {
    return JSON.parse(c) as Record<string, unknown>
  } catch {
    return {}
  }
}

/**
 * Map each value → a valid option (or null). Only values that resolve to an
 * actual member of `options` are returned; anything else is null.
 */
export async function aiMatchEnumValues(
  values: string[],
  options: string[],
  ctx: { colId: string; colLabel?: string },
): Promise<Record<string, string | null>> {
  const out: Record<string, string | null> = Object.fromEntries(values.map((v) => [v, null]))
  if (!values.length || !options.length || isAiKillSwitchOn()) return out
  const provider = getProvider(null)
  if (!provider) return out

  const sample = options.slice(0, 80)
  const prompt = [
    `You are matching imported product attribute values to a fixed list of allowed Amazon options.`,
    ``,
    `Field: "${ctx.colId}"${ctx.colLabel ? ` (${ctx.colLabel})` : ''}`,
    ``,
    `Imported values to match:`,
    ...values.map((v) => `- ${v}`),
    ``,
    `Allowed options:`,
    ...sample.map((o) => `- ${o}`),
    options.length > 80 ? `... (${options.length - 80} more omitted)` : '',
    ``,
    `For each imported value, return the single best-matching option from the allowed list`,
    `(exact string, case-sensitive). If none is a reasonable match, return null.`,
    `Return strict JSON only:`,
    `{`,
    ...values.map((v) => `  ${JSON.stringify(v)}: "<option or null>",`),
    `}`,
  ].filter((l) => l !== undefined && l !== '').join('\n')

  const startedAt = Date.now()
  try {
    const res = await provider.generate({ prompt, jsonMode: true, maxOutputTokens: 1024, temperature: 0.1, feature: 'ff-coerce-enum' })
    logUsage({
      provider: res.usage.provider, model: res.usage.model, feature: 'ff-coerce-enum',
      inputTokens: res.usage.inputTokens, outputTokens: res.usage.outputTokens, costUSD: res.usage.costUSD,
      latencyMs: Date.now() - startedAt, ok: true, metadata: { colId: ctx.colId, valueCount: values.length },
    })
    const parsed = parseJsonObject(res.text)
    const byLower = new Map(options.map((o) => [o.toLowerCase(), o]))
    for (const v of values) {
      const m = parsed[v]
      const s = typeof m === 'string'
        ? m.trim()
        : (m && typeof m === 'object' && typeof (m as Record<string, unknown>).match === 'string'
            ? String((m as Record<string, unknown>).match).trim() : '')
      if (s && s !== 'null' && s !== 'NO_MATCH') out[v] = byLower.get(s.toLowerCase()) ?? null
    }
  } catch (err) {
    logUsage({
      provider: provider.name, model: provider.defaultModel, feature: 'ff-coerce-enum',
      inputTokens: 0, outputTokens: 0, costUSD: 0, latencyMs: Date.now() - startedAt,
      ok: false, errorMessage: err instanceof Error ? err.message : String(err),
    })
  }
  return out
}

/**
 * Pure coercion (flat-file-coerce.coerceRows) + an optional AI pass that rescues
 * flagged ENUM cells via semantic matching. AI runs one call per affected enum
 * column (distinct flagged values batched). Rescued cells flip flagged→coerced.
 */
export async function coerceRowsWithAi(
  rows: Record<string, unknown>[],
  columns: CoercibleColumnWithId[],
  opts: { ai: boolean; colLabels?: Map<string, string> },
): Promise<CoerceRowsResult> {
  const base = coerceRows(rows, columns)
  if (!opts.ai) return base

  const byId = new Map(columns.map((c) => [c.id, c]))
  const flaggedByCol = new Map<string, Set<string>>()
  for (const iss of base.issues) {
    if (iss.status !== 'flagged') continue
    const col = byId.get(iss.columnId)
    if (col?.kind === 'enum' && col.options?.length) {
      if (!flaggedByCol.has(iss.columnId)) flaggedByCol.set(iss.columnId, new Set())
      flaggedByCol.get(iss.columnId)!.add(iss.from)
    }
  }
  if (!flaggedByCol.size) return base

  const resolved = new Map<string, Record<string, string | null>>()
  await Promise.all(
    [...flaggedByCol].map(async ([colId, vals]) => {
      const col = byId.get(colId)!
      resolved.set(colId, await aiMatchEnumValues([...vals], col.options ?? [], { colId, colLabel: opts.colLabels?.get(colId) }))
    }),
  )

  let { ok, coerced, flagged } = base.counts
  const rowsOut = base.rows.map((r) => ({ ...r }))
  const issuesOut = base.issues.map((iss) => {
    if (iss.status === 'flagged') {
      const match = resolved.get(iss.columnId)?.[iss.from]
      if (match) {
        rowsOut[iss.rowIndex][iss.columnId] = match
        flagged--; coerced++
        return { ...iss, status: 'coerced' as const, to: match, note: `AI matched "${match}"` }
      }
    }
    return iss
  })

  return { rows: rowsOut, issues: issuesOut, counts: { ok, coerced, flagged } }
}

/**
 * FX.4 — value coercion for external-file import into the Amazon flat-file grid.
 *
 * After FX.3 maps an external header onto a flat-file column, the VALUE still
 * has to fit that column's type/enum/limits. This engine coerces a raw external
 * value to the column's shape and reports one of three states so the FX.5
 * preview can colour it:
 *   • ok      — already valid, used as-is
 *   • coerced — changed to become valid (enum option matched, EU number parsed,
 *               boolean canonicalized, whitespace trimmed)
 *   • flagged — could NOT be made valid (unknown enum, unparseable number,
 *               over-length text) — original kept, never silently dropped
 *
 * Deterministic + pure (no DB, no AI). The AI semantic-match for flagged enum
 * cells (e.g. "rosso" → "Red") is a separate async layer in flat-file-coerce-ai.
 */

import type { FlatFileColumn } from './flat-file.service.js'
import { parseLocaleNumber } from '../../lib/parse-locale-number.js'

export type CoerceStatus = 'ok' | 'coerced' | 'flagged'

export interface CoercedCell {
  value: string
  status: CoerceStatus
  changed: boolean
  note?: string
}

export type CoercibleColumn = Pick<FlatFileColumn, 'kind' | 'options' | 'maxLength'>
export type CoercibleColumnWithId = Pick<FlatFileColumn, 'id' | 'kind' | 'options' | 'maxLength'>

// Boolean tokens kept as lowercase (NOT normalized) so accented forms like "sì"
// survive. Covers EN + the EU market languages (IT/DE/FR/ES).
const TRUE_TOKENS = new Set(['true', 't', 'yes', 'y', '1', 'x', 'si', 'sì', 'vero', 'ja', 'wahr', 'oui', 'sí'])
const FALSE_TOKENS = new Set(['false', 'f', 'no', 'n', '0', 'falso', 'nein', 'falsch', 'non'])

function norm(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '')
}

export function coerceValue(raw: unknown, column: CoercibleColumn): CoercedCell {
  const original = raw == null ? '' : String(raw)
  const trimmed = original.trim()
  // Empty cells: nothing to coerce. Required-ness is a pre-flight concern (A5/MT.2).
  if (trimmed === '') return { value: '', status: 'ok', changed: original !== '' }

  const done = (value: string, status: CoerceStatus, note?: string): CoercedCell => ({
    value, status, changed: value !== original, note,
  })

  switch (column.kind) {
    case 'enum': {
      const opts = column.options ?? []
      if (!opts.length) return done(trimmed, 'ok') // free-typed enum (no constrained list)
      const exact = opts.find((o) => o === trimmed)
      if (exact) return done(exact, exact === original ? 'ok' : 'coerced')
      const ci = opts.find((o) => o.toLowerCase() === trimmed.toLowerCase())
      if (ci) return done(ci, 'coerced', `Matched option "${ci}"`)
      const n = norm(trimmed)
      const nm = n ? opts.find((o) => norm(o) === n) : undefined
      if (nm) return done(nm, 'coerced', `Matched option "${nm}"`)
      return done(trimmed, 'flagged', `"${trimmed}" is not a valid option`)
    }
    case 'number': {
      const n = parseLocaleNumber(trimmed)
      if (n == null) return done(trimmed, 'flagged', `"${trimmed}" is not a number`)
      const s = String(n)
      return done(s, s === original ? 'ok' : 'coerced')
    }
    case 'boolean': {
      const t = trimmed.toLowerCase()
      if (TRUE_TOKENS.has(t)) return done('true', original === 'true' ? 'ok' : 'coerced')
      if (FALSE_TOKENS.has(t)) return done('false', original === 'false' ? 'ok' : 'coerced')
      const ci = (column.options ?? []).find((o) => o.toLowerCase() === t)
      if (ci) return done(ci, ci === original ? 'ok' : 'coerced')
      return done(trimmed, 'flagged', `"${trimmed}" is not true/false`)
    }
    default: {
      // 'text' | 'longtext'
      if (column.maxLength && trimmed.length > column.maxLength) {
        return done(trimmed, 'flagged', `Exceeds max length ${column.maxLength} (is ${trimmed.length})`)
      }
      return done(trimmed, trimmed === original ? 'ok' : 'coerced')
    }
  }
}

export interface CellIssue {
  rowIndex: number
  columnId: string
  status: Exclude<CoerceStatus, 'ok'>
  from: string
  to: string
  note?: string
}

export interface CoerceRowsResult {
  rows: Record<string, unknown>[]
  issues: CellIssue[]
  counts: { ok: number; coerced: number; flagged: number }
}

/**
 * Coerce every cell of every row whose key matches a known column. Structural
 * keys (_rowId, product_type, …) and any header that isn't a flat-file column
 * pass through untouched. Non-'ok' cells are reported as issues for the preview.
 */
export function coerceRows(
  rows: Record<string, unknown>[],
  columns: CoercibleColumnWithId[],
): CoerceRowsResult {
  const byId = new Map(columns.map((c) => [c.id, c]))
  const out: Record<string, unknown>[] = []
  const issues: CellIssue[] = []
  let ok = 0, coerced = 0, flagged = 0

  rows.forEach((row, rowIndex) => {
    const next: Record<string, unknown> = { ...row }
    for (const [key, val] of Object.entries(row)) {
      const col = byId.get(key)
      if (!col) continue
      const r = coerceValue(val, col)
      next[key] = r.value
      if (r.status === 'ok') {
        ok++
      } else {
        if (r.status === 'coerced') coerced++
        else flagged++
        issues.push({ rowIndex, columnId: key, status: r.status, from: val == null ? '' : String(val), to: r.value, note: r.note })
      }
    }
    out.push(next)
  })

  return { rows: out, issues, counts: { ok, coerced, flagged } }
}

/**
 * FX.4 — value coercion engine. Pure, so enum match (exact/case/normalized),
 * EU-locale numbers, booleans, max-length flagging, and the row-batch issue
 * accounting are fully unit-testable without AI or a DB.
 */
import { describe, it, expect } from 'vitest'
import { coerceValue, coerceRows } from './flat-file-coerce.js'

const enumCol = (options: string[]) => ({ kind: 'enum' as const, options })
const numCol = { kind: 'number' as const }
const boolCol = { kind: 'boolean' as const }
const textCol = (maxLength?: number) => ({ kind: 'text' as const, maxLength })

describe('FX.4 — coerceValue: enum', () => {
  const col = enumCol(['Red', 'Black', 'Hi-Vis Yellow'])
  it('exact option → ok', () => expect(coerceValue('Red', col)).toMatchObject({ value: 'Red', status: 'ok' }))
  it('case-insensitive → coerced to the canonical option', () =>
    expect(coerceValue('black', col)).toMatchObject({ value: 'Black', status: 'coerced' }))
  it('normalized (punctuation/space) → coerced', () =>
    expect(coerceValue('hi vis yellow', col)).toMatchObject({ value: 'Hi-Vis Yellow', status: 'coerced' }))
  it('no match → flagged, original kept', () =>
    expect(coerceValue('Purple', col)).toMatchObject({ value: 'Purple', status: 'flagged' }))
  it('enum with no option list → passes through as ok', () =>
    expect(coerceValue('Anything', enumCol([]))).toMatchObject({ value: 'Anything', status: 'ok' }))
})

describe('FX.4 — coerceValue: number (EU locale)', () => {
  it('EU decimal comma → dot', () => expect(coerceValue('129,90', numCol)).toMatchObject({ value: '129.9', status: 'coerced' }))
  it('EU thousands + decimal', () => expect(coerceValue('1.234,56', numCol)).toMatchObject({ value: '1234.56', status: 'coerced' }))
  it('strips a currency symbol', () => expect(coerceValue('€ 89', numCol)).toMatchObject({ value: '89', status: 'coerced' }))
  it('already clean → ok', () => expect(coerceValue('42', numCol)).toMatchObject({ value: '42', status: 'ok' }))
  it('non-numeric → flagged', () => expect(coerceValue('N/A', numCol)).toMatchObject({ value: 'N/A', status: 'flagged' }))
})

describe('FX.4 — coerceValue: boolean', () => {
  it('yes → true', () => expect(coerceValue('Yes', boolCol)).toMatchObject({ value: 'true', status: 'coerced' }))
  it('Italian "sì" → true', () => expect(coerceValue('sì', boolCol)).toMatchObject({ value: 'true', status: 'coerced' }))
  it('0 → false', () => expect(coerceValue('0', boolCol)).toMatchObject({ value: 'false', status: 'coerced' }))
  it('already "true" → ok', () => expect(coerceValue('true', boolCol)).toMatchObject({ value: 'true', status: 'ok' }))
  it('garbage → flagged', () => expect(coerceValue('maybe', boolCol)).toMatchObject({ status: 'flagged' }))
})

describe('FX.4 — coerceValue: text', () => {
  it('within max length → ok (trimmed)', () =>
    expect(coerceValue('  Jacket  ', textCol(50))).toMatchObject({ value: 'Jacket', status: 'coerced' }))
  it('over max length → flagged (kept, not truncated)', () => {
    const r = coerceValue('abcdefghij', textCol(5))
    expect(r).toMatchObject({ value: 'abcdefghij', status: 'flagged' })
    expect(r.note).toContain('max length 5')
  })
  it('empty stays empty + ok', () => expect(coerceValue('', textCol())).toMatchObject({ value: '', status: 'ok' }))
})

describe('FX.4 — coerceRows: batch + issue accounting', () => {
  const columns = [
    { id: 'item_sku', kind: 'text' as const },
    { id: 'standard_price', kind: 'number' as const },
    { id: 'color_name', kind: 'enum' as const, options: ['Red', 'Black'] },
  ]
  const rows = [
    { _rowId: 'r1', item_sku: 'A1', standard_price: '129,90', color_name: 'black', not_a_column: 'left alone' },
    { _rowId: 'r2', item_sku: 'A2', standard_price: 'oops', color_name: 'Purple' },
  ]
  const out = coerceRows(rows, columns)

  it('coerces matched cells + leaves unknown/structural keys untouched', () => {
    expect(out.rows[0]).toMatchObject({ standard_price: '129.9', color_name: 'Black', not_a_column: 'left alone', _rowId: 'r1' })
  })
  it('flags the bad number + the unknown enum, keeping originals', () => {
    expect(out.rows[1]).toMatchObject({ standard_price: 'oops', color_name: 'Purple' })
  })
  it('counts ok/coerced/flagged and lists issues with row index + column', () => {
    expect(out.counts).toEqual({ ok: 2, coerced: 2, flagged: 2 })
    expect(out.issues.filter((i) => i.status === 'flagged').map((i) => i.columnId).sort())
      .toEqual(['color_name', 'standard_price'])
    expect(out.issues.find((i) => i.columnId === 'color_name' && i.rowIndex === 1)).toMatchObject({ from: 'Purple', status: 'flagged' })
  })
})

/**
 * FFC — flat-file product-creation mapping. Pure, so the row → Product.create
 * mapping (incl. variants, identifiers, localized content, fallbacks) is fully
 * unit-testable without the DB.
 */
import { describe, it, expect } from 'vitest'
import {
  buildProductCreateInput,
  ffcCollectBullets,
  ffcExtractVariantAxes,
