/**
 * FX.5 — import merge planner.
 *
 * Given the current grid rows (existing) and the mapped+coerced import rows
 * (incoming), compute a PLAN describing exactly what an apply would do — matched
 * by item_sku — so the wizard can show a per-row / per-cell diff and the
 * operator can choose what lands. The plan is mode-aware:
 *   • fill-missing — write only where the existing cell is BLANK (never
 *     overwrites existing data) — the default
 *   • overwrite    — write every mapped value, replacing what's there
 * A column allowlist (the operator's column selection) and addNewRows (whether
 * an unknown SKU becomes a new row) further scope it. Each shown cell carries a
 * willApply flag + reason so the UI can render + the apply step can act on it.
 *
 * Pure: no DB, no AI. The client sends its in-memory rows in and renders the
 * plan; per-cell toggles flip willApply locally, a mode/column change re-plans.
 */

export type ImportApplyMode = 'fill-missing' | 'overwrite'

export type PlanCellReason = 'fill' | 'overwrite' | 'skip-existing' | 'skip-column'

export interface PlanCell {
  columnId: string
  from: string
  to: string
  willApply: boolean
  reason: PlanCellReason
}

export interface PlanNewRow {
  sku: string
  cells: PlanCell[]
}

export interface PlanUpdate {
  sku: string
  /** The existing row's _rowId, echoed so the client can apply in place. */
  rowId: string
  cells: PlanCell[]
}

export interface ImportMergePlan {
  newRows: PlanNewRow[]
  updates: PlanUpdate[]
  /** Incoming rows with a blank match key — can't match or create. */
  skippedNoSku: number
  /** Incoming rows collapsed because they repeated an earlier SKU (later non-blank cell wins). */
  duplicateSkus: number
  /** When addNewRows=false: incoming SKUs absent from the grid (ignored). */
  unmatchedSkipped: string[]
  stats: { newRows: number; updatedRows: number; cellsToApply: number; cellsToSkip: number }
}

export interface PlanOptions {
  mode: ImportApplyMode
  /** Allowlist of column ids the operator chose; null/empty = all incoming columns. */
  columns?: string[] | null
  /** Match key for row identity. Default 'item_sku'. */
  matchKey?: string
  /** Whether an incoming SKU absent from the grid becomes a new row. Default true. */
  addNewRows?: boolean
}

const META_KEYS = new Set(['_rowId', '_isNew', '_dirty', '_status', '_feedMessage', '_productId'])

const str = (v: unknown): string => (v == null ? '' : String(v))
const isBlank = (v: unknown): boolean => str(v).trim() === ''

/**
 * Collapse incoming rows that repeat a SKU into one (later non-blank cell wins),
 * so a supplier file listing the same SKU twice doesn't create two new rows or
 * fight itself on update. Blank-SKU rows are kept (counted as no-SKU downstream).
 */
export function dedupeBySku(
  rows: Record<string, unknown>[],
  matchKey = 'item_sku',
): { rows: Record<string, unknown>[]; duplicates: number } {
  const bySku = new Map<string, Record<string, unknown>>()
  const order: string[] = []
  const noSku: Record<string, unknown>[] = []
  let duplicates = 0
  for (const r of rows) {
    const sku = str(r[matchKey]).trim()
    if (!sku) { noSku.push(r); continue }
    const existing = bySku.get(sku)
    if (!existing) { bySku.set(sku, { ...r }); order.push(sku); continue }
    duplicates++
    for (const [k, v] of Object.entries(r)) if (!isBlank(v)) existing[k] = v
  }
  return { rows: [...order.map((s) => bySku.get(s)!), ...noSku], duplicates }
}

export function planImportMerge(
  existing: Record<string, unknown>[],
  incomingRaw: Record<string, unknown>[],
  options: PlanOptions,
): ImportMergePlan {
  const matchKey = options.matchKey ?? 'item_sku'
  const { rows: incoming, duplicates: duplicateSkus } = dedupeBySku(incomingRaw, matchKey)
  const addNew = options.addNewRows !== false
  const allow = options.columns && options.columns.length ? new Set(options.columns) : null

  const bySku = new Map<string, Record<string, unknown>>()
  for (const r of existing) {
    const sku = str(r[matchKey]).trim()
    if (sku && !bySku.has(sku)) bySku.set(sku, r)
  }

  const newRows: PlanNewRow[] = []
  const updates: PlanUpdate[] = []
  const unmatchedSkipped: string[] = []
  let skippedNoSku = 0
  let cellsToApply = 0
  let cellsToSkip = 0
  const bump = (apply: boolean) => { if (apply) cellsToApply++; else cellsToSkip++ }

  for (const inc of incoming) {
    const sku = str(inc[matchKey]).trim()
    if (!sku) { skippedNoSku++; continue }
    const cols = Object.keys(inc).filter((k) => !META_KEYS.has(k))
    const match = bySku.get(sku)

    if (match) {
      const cells: PlanCell[] = []
      for (const columnId of cols) {
        const to = str(inc[columnId])
        const from = str(match[columnId])
        if (to === from || isBlank(to)) continue // unchanged or nothing to write
        let willApply: boolean
        let reason: PlanCellReason
        if (allow && !allow.has(columnId)) { willApply = false; reason = 'skip-column' }
        else if (options.mode === 'fill-missing' && !isBlank(from)) { willApply = false; reason = 'skip-existing' }
        else { willApply = true; reason = isBlank(from) ? 'fill' : 'overwrite' }
        cells.push({ columnId, from, to, willApply, reason })
        bump(willApply)
      }
      if (cells.length) updates.push({ sku, rowId: str(match['_rowId']), cells })
    } else if (addNew) {
      const cells: PlanCell[] = []
      for (const columnId of cols) {
        const to = str(inc[columnId])
        if (isBlank(to)) continue
        const willApply = !allow || allow.has(columnId)
        cells.push({ columnId, from: '', to, willApply, reason: willApply ? 'fill' : 'skip-column' })
        bump(willApply)
      }
      newRows.push({ sku, cells })
    } else {
      unmatchedSkipped.push(sku)
    }
  }

  return {
    newRows,
    updates,
    skippedNoSku,
    duplicateSkus,
    unmatchedSkipped,
    stats: { newRows: newRows.length, updatedRows: updates.length, cellsToApply, cellsToSkip },
  }
}

/**
 * FX.5 — import merge planner. Pure, so fill-missing vs overwrite, new-vs-update
 * by item_sku, the column allowlist, blank/unchanged skipping, and the apply/skip
 * accounting are fully unit-testable.
 */
import { describe, it, expect } from 'vitest'
import { planImportMerge, dedupeBySku } from './flat-file-merge.js'

const existing = [
  { _rowId: 'r1', item_sku: 'A1', item_name: 'Jacket', standard_price: '100', color_name: '' },
  { _rowId: 'r2', item_sku: 'A2', item_name: '', standard_price: '50', color_name: 'Red' },
]

describe('FX.5 — planImportMerge: fill-missing (default)', () => {
  const incoming = [
    { item_sku: 'A1', item_name: 'Jacket Pro', color_name: 'Black' }, // name conflicts (skip), color blank→fill
    { item_sku: 'A3', item_name: 'Gloves', standard_price: '30' },     // new row
  ]
  const plan = planImportMerge(existing, incoming, { mode: 'fill-missing' })

  it('updates an existing SKU only where the grid cell is blank', () => {
    const u = plan.updates.find((u) => u.sku === 'A1')!
    expect(u.rowId).toBe('r1')
    const name = u.cells.find((c) => c.columnId === 'item_name')!
    const color = u.cells.find((c) => c.columnId === 'color_name')!
    expect(name).toMatchObject({ from: 'Jacket', to: 'Jacket Pro', willApply: false, reason: 'skip-existing' })
    expect(color).toMatchObject({ from: '', to: 'Black', willApply: true, reason: 'fill' })
  })
  it('adds an unknown SKU as a new row (all cells fill)', () => {
    const n = plan.newRows.find((n) => n.sku === 'A3')!
    expect(n.cells.every((c) => c.willApply && c.reason === 'fill' && c.from === '')).toBe(true)
    expect(n.cells.map((c) => c.columnId).sort()).toEqual(['item_name', 'item_sku', 'standard_price'])
  })
  it('accounts apply vs skip', () => {
    // A1: color fill (apply) + name skip-existing (skip); A3: 3 cells apply
    expect(plan.stats).toMatchObject({ newRows: 1, updatedRows: 1, cellsToApply: 4, cellsToSkip: 1 })
  })
})

describe('FX.5 — planImportMerge: overwrite', () => {
  const incoming = [{ item_sku: 'A1', item_name: 'Jacket Pro' }]
  const plan = planImportMerge(existing, incoming, { mode: 'overwrite' })
  it('writes over an existing non-blank cell', () => {
    const name = plan.updates[0].cells.find((c) => c.columnId === 'item_name')!
    expect(name).toMatchObject({ from: 'Jacket', to: 'Jacket Pro', willApply: true, reason: 'overwrite' })
  })
})

describe('FX.5 — column allowlist + unchanged/blank skipping', () => {
  it('columns not in the allowlist are shown but not applied', () => {
    const incoming = [{ item_sku: 'A2', item_name: 'Pants', color_name: 'Blue' }]
    const plan = planImportMerge(existing, incoming, { mode: 'overwrite', columns: ['item_name'] })
    const u = plan.updates[0]
    expect(u.cells.find((c) => c.columnId === 'item_name')).toMatchObject({ willApply: true })
    expect(u.cells.find((c) => c.columnId === 'color_name')).toMatchObject({ willApply: false, reason: 'skip-column' })
  })
  it('unchanged + blank incoming cells are dropped from the diff', () => {
    const incoming = [{ item_sku: 'A1', item_name: 'Jacket', color_name: '' }] // name same, color blank
    const plan = planImportMerge(existing, incoming, { mode: 'overwrite' })
    expect(plan.updates).toEqual([]) // nothing to show
  })
})

describe('FX.5 — addNewRows=false + blank-sku', () => {
  it('skips unknown SKUs instead of creating rows', () => {
    const incoming = [{ item_sku: 'ZZ', item_name: 'X' }]
    const plan = planImportMerge(existing, incoming, { mode: 'overwrite', addNewRows: false })
    expect(plan.newRows).toEqual([])
    expect(plan.unmatchedSkipped).toEqual(['ZZ'])
  })
