      { item_sku: 'NEW', item_name: 'A' },
      { item_sku: 'NEW', standard_price: '10' },
    ], { mode: 'overwrite' })
    expect(plan.duplicateSkus).toBe(1)
    expect(plan.newRows).toHaveLength(1)
  })
})

apps/api/src/services/amazon/flat-file-p.content:
/**
 * Flat-File Propagate Service
 *
 * Copies flat-file data from a source marketplace to one or more target
 * marketplaces for the same product type. Used when products are already
 * live on all markets and you want to hydrate the flat file editor for
 * each market from an already-pulled source rather than calling Amazon
 * again per market.
 *
 * Per target market:
 *   1. Verbatim copy of all structural + numeric + image fields
 *   2. AI text translation of title / description / bullet points (optional)
 *   3. AI enum mapping of locale-specific option values (optional)
 *   4. Sync to ChannelListing via syncRowsToPlatform
 *
 * Job lifecycle matches flat-file-pull.service — in-memory, polled every 3 s.
 */

import prisma from '../../db.js'
import { getProvider, isAiKillSwitchOn } from '../ai/providers/index.js'
import { logUsage } from '../ai/usage-logger.service.js'
import { AmazonService } from '../marketplaces/amazon.service.js'
import { AmazonFlatFileService } from './flat-file.service.js'
import { CategorySchemaService } from '../categories/schema-sync.service.js'
import { translateEnumValues } from './value-translate.service.js'
import type { FlatFileRow } from './flat-file.service.js'

// ── Language maps ──────────────────────────────────────────────────────────

const MARKET_LANGUAGE: Record<string, string> = {
  IT: 'Italian', DE: 'German', FR: 'French', ES: 'Spanish', UK: 'English (UK)',
}

// Fields that carry locale-specific free text and should be AI-translated
const TEXT_FIELDS = [
  'item_name',
  'product_description',
  'generic_keyword',
  'bullet_point',
  'bullet_point_1', 'bullet_point_2', 'bullet_point_3',
  'bullet_point_4', 'bullet_point_5',
]

// Fields that are market-agnostic and must never be translated
const SKIP_TRANSLATE = new Set([
  // Internal
  '_rowId', '_productId', '_isNew', '_dirty', '_status', '_feedMessage', '_asin', '_listingStatus',
  // Structural
  'item_sku', 'product_type', 'record_action', 'parentage_level', 'parent_sku', 'variation_theme',
  // Pricing / qty (user adjusts per market)
  'purchasable_offer', 'standard_price', 'sale_price', 'fulfillment_availability', 'quantity',
  // Images
  'main_product_image_locator', 'swatch_image_locator',
  'other_image_locator_1', 'other_image_locator_2', 'other_image_locator_3', 'other_image_locator_4',
])

// ── Job types ──────────────────────────────────────────────────────────────

export interface PropagateMarketState {
  status: 'pending' | 'running' | 'done' | 'failed'
  phase: 'copy' | 'text' | 'enums' | 'sync' | 'idle'
  translated: number
  total: number
  errors: string[]
  rows: any[]
}

export interface PropagateJob {
  jobId: string
  sourceMarket: string
  targetMarkets: string[]
  productType: string
  options: { translateText: boolean; translateEnums: boolean }
  status: 'running' | 'done' | 'failed'
  markets: Record<string, PropagateMarketState>
  startedAt: string
  doneAt?: string
  fatalError?: string
}

// ── In-memory store ────────────────────────────────────────────────────────

const JOB_TTL_MS = 2 * 60 * 60 * 1000
const propagateJobs = new Map<string, PropagateJob>()

function prune() {
  const cutoff = Date.now() - JOB_TTL_MS
  for (const [id, job] of propagateJobs) {
    if (new Date(job.startedAt).getTime() < cutoff) propagateJobs.delete(id)
  }
}

// ── Public API ─────────────────────────────────────────────────────────────

export function startPropagateJob(
  sourceMarket: string,
  targetMarkets: string[],
  productType: string,
  options: { translateText: boolean; translateEnums: boolean },
): string {
  prune()
  const jobId = `ffprop-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
  const markets: PropagateJob['markets'] = {}
  for (const mp of targetMarkets) {
    markets[mp.toUpperCase()] = {
      status: 'pending', phase: 'idle', translated: 0, total: 0, errors: [], rows: [],
    }
  }
  const job: PropagateJob = {
    jobId,
    sourceMarket: sourceMarket.toUpperCase(),
    targetMarkets: targetMarkets.map((m) => m.toUpperCase()),
    productType: productType.toUpperCase(),
    options,
    status: 'running',
    markets,
    startedAt: new Date().toISOString(),
  }
  propagateJobs.set(jobId, job)
  void runPropagateJob(job).catch((err) => {
    job.status = 'failed'
    job.fatalError = err instanceof Error ? err.message : String(err)
    job.doneAt = new Date().toISOString()
  })
  return jobId
}

export function getPropagateJobStatus(jobId: string): PropagateJob | null {
  return propagateJobs.get(jobId) ?? null
}

// ── Core job ───────────────────────────────────────────────────────────────

async function runPropagateJob(job: PropagateJob): Promise<void> {
  const { sourceMarket, productType, targetMarkets, options } = job

  const amazon = new AmazonService()
  const schemaService = new CategorySchemaService(prisma, amazon)
  const flatFileService = new AmazonFlatFileService(prisma, schemaService)

  // Load source rows — must have been pulled from Amazon already
  const sourceRows = await flatFileService.getExistingRows(sourceMarket, productType)
  if (!sourceRows.length) {
    job.status = 'failed'
    job.fatalError = `No rows for ${sourceMarket}/${productType} — pull from Amazon first`
    job.doneAt = new Date().toISOString()
    return
  }

  // Get source manifest for expandedFields (needed by syncRowsToPlatform)
  let expandedFields: Record<string, string> = {}
  try {
    const manifest = await flatFileService.generateManifest(sourceMarket, productType)
    expandedFields = manifest?.expandedFields ?? {}
  } catch { /* proceed without — sync will use generic collapse */ }

  // Process target markets sequentially (rate-limit friendly for AI calls)
  for (const targetMarket of targetMarkets) {
    const state = job.markets[targetMarket]
    state.status = 'running'
    state.total = sourceRows.length

    try {
      // 1. Verbatim copy
      state.phase = 'copy'
      let rows: FlatFileRow[] = sourceRows.map((r) => ({ ...r, _dirty: true, _status: 'idle' as const }))

      // 2. Translate text fields
      if (options.translateText) {
        state.phase = 'text'
        rows = await translateTextBatch(rows, sourceMarket, targetMarket)
      }

      // 3. Translate enum values
      if (options.translateEnums) {
        state.phase = 'enums'
        rows = await translateEnumBatch(rows, sourceMarket, targetMarket, productType)
      }

      // 4. Sync to platform DB
      state.phase = 'sync'
      await flatFileService.syncRowsToPlatform(rows, targetMarket, expandedFields, { isPublished: false })

      state.rows = rows
      state.translated = rows.length
      state.status = 'done'
      state.phase = 'idle'
    } catch (err: any) {
      state.status = 'failed'
      state.phase = 'idle'
      state.errors.push(err?.message ?? 'Failed')
    }
  }

  job.status = 'done'
  job.doneAt = new Date().toISOString()
}

// ── Text translation ───────────────────────────────────────────────────────

async function translateTextBatch(
  rows: FlatFileRow[],
  sourceMarket: string,
  targetMarket: string,
): Promise<FlatFileRow[]> {
  if (isAiKillSwitchOn()) return rows
  const provider = getProvider(null)
  if (!provider) return rows

  const srcLang = MARKET_LANGUAGE[sourceMarket] ?? sourceMarket
  const tgtLang = MARKET_LANGUAGE[targetMarket] ?? targetMarket

  // Build flat key-value batch: "r{i}_{field}" → value
  const batch: Record<string, string> = {}
  for (let i = 0; i < rows.length; i++) {
    for (const field of TEXT_FIELDS) {
      const val = String(rows[i][field] ?? '').trim()
      if (val) batch[`r${i}_${field}`] = val
    }
  }
  if (!Object.keys(batch).length) return rows

  const prompt = [
    `Translate these Amazon product listing fields from ${srcLang} to ${tgtLang}.`,
    `Rules:`,
    `- Keep brand names, model names, sizes, and technical measurements unchanged.`,
    `- Do not add or remove any keys.`,
    `- Return strict JSON only — no commentary.`,
    ``,
    JSON.stringify(batch, null, 2),
  ].join('\n')

  const startedAt = Date.now()
  try {
    const res = await provider.generate({
      prompt,
      jsonMode: true,
      maxOutputTokens: 4096,
      temperature: 0.1,
      feature: 'ff-propagate-text',
    })
    logUsage({
      provider: res.usage.provider,
      model: res.usage.model,
      feature: 'ff-propagate-text',
      inputTokens: res.usage.inputTokens,
      outputTokens: res.usage.outputTokens,
      costUSD: res.usage.costUSD,
      latencyMs: Date.now() - startedAt,
      ok: true,
    })

    let translated: Record<string, string> = {}
    try {
      const raw = res.text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '')
      translated = JSON.parse(raw)
    } catch { return rows }

    return rows.map((row, i) => {
      const updated = { ...row }
      for (const field of TEXT_FIELDS) {
        const key = `r${i}_${field}`
        if (translated[key] && typeof translated[key] === 'string') {
          updated[field] = translated[key]
        }
      }
      return updated
    })
  } catch (err) {
    logUsage({
      provider: provider.name,
      model: provider.defaultModel,
      feature: 'ff-propagate-text',
      inputTokens: 0, outputTokens: 0, costUSD: 0,
      latencyMs: Date.now() - startedAt,
      ok: false,
      errorMessage: err instanceof Error ? err.message : String(err),
    })
    return rows
  }
}

// ── Enum translation ───────────────────────────────────────────────────────

async function translateEnumBatch(
  rows: FlatFileRow[],
  sourceMarket: string,
  targetMarket: string,
  productType: string,
): Promise<FlatFileRow[]> {
  // Collect candidate columns: non-structural, non-text, non-numeric string values
  const candidates = new Map<string, Set<string>>() // colId → distinct values
  for (const row of rows) {
    for (const [k, v] of Object.entries(row)) {
      if (
        k.startsWith('_') ||
        SKIP_TRANSLATE.has(k) ||
        TEXT_FIELDS.includes(k) ||
        !v || typeof v !== 'string' || !v.trim() ||
        k.includes('image_locator') ||
        !isNaN(Number(v))
      ) continue
      if (!candidates.has(k)) candidates.set(k, new Set())
      candidates.get(k)!.add(v.trim())
    }
  }
  if (!candidates.size) return rows

  const updatedRows = rows.map((r) => ({ ...r }))

  // Translate each candidate column — translateEnumValues handles "no enum options" gracefully
  for (const [colId, valueSet] of candidates) {
    const values = [...valueSet]
    try {
      const result = await translateEnumValues(prisma, {
        sourceMarket,
        productType,
        colId,
        values,
        targetMarkets: [targetMarket],
      })
      const mappings = result.mappings[targetMarket.toUpperCase()]
      if (!mappings) continue

      for (const row of updatedRows) {
        const srcVal = String(row[colId] ?? '').trim()
        if (!srcVal) continue
        const mapping = mappings[srcVal]
        if (mapping?.match && mapping.valid) row[colId] = mapping.match
      }
    } catch { /* skip column on error */ }
  }

  return updatedRows
}

/**
 * Flat-File Pull Preview Service
 *
 * Non-destructive sibling of flat-file-pull.service.ts. Same SP-API calls,
 * same row expansion, but the pulled data is held in memory only — never
 * written to ChannelListing / Product / ProductVariation.
 *
 * Used by /products/amazon-flat-file so a user can pull fresh data from
 * Amazon directly into the editor's local row state, review it, undo via
 * Cmd+Z, and persist only when they click Save.
 *
 * The reconciliation pull (which DOES write to DB) is left untouched.
 */

import prisma from '../../db.js'
import { AmazonService } from '../marketplaces/amazon.service.js'
import {
  MARKETPLACE_ID_MAP,
  CURRENCY_MAP,
  type FlatFileRow,
} from './flat-file.service.js'
import {
  persistPullJobInitial,
  persistPullJobFinal,
} from '../flat-file-pull-job-store.js'

export interface PullPreviewJob {
  jobId: string
  marketplace: string
  productType: string
  skus: string[] | null
  status: 'running' | 'done' | 'failed'
  progress: number
  total: number
  pulled: number
  skipped: number
  failed: number
  errors: Array<{ sku: string; error: string }>
  rows: FlatFileRow[]
  startedAt: string
  doneAt?: string
  fatalError?: string
}

const JOB_TTL_MS = 2 * 60 * 60 * 1000
const jobs = new Map<string, PullPreviewJob>()

function pruneOldJobs(): void {
  const cutoff = Date.now() - JOB_TTL_MS
  for (const [id, j] of jobs) {
    if (new Date(j.startedAt).getTime() < cutoff) jobs.delete(id)
  }
}

export function startPullPreviewJob(opts: {
  marketplace: string
  productType: string
  skus?: string[]
}): string {
  pruneOldJobs()
  const jobId = `ffpreview-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
  const job: PullPreviewJob = {
    jobId,
    marketplace: opts.marketplace.toUpperCase(),
    productType: opts.productType.toUpperCase(),
    skus: opts.skus && opts.skus.length > 0 ? opts.skus.slice() : null,
    status: 'running',
    progress: 0,
    total: 0,
    pulled: 0,
    skipped: 0,
    failed: 0,
    errors: [],
    rows: [],
    startedAt: new Date().toISOString(),
  }
  jobs.set(jobId, job)
  void persistPullJobInitial('AMAZON', {
    jobId: job.jobId,
    marketplace: job.marketplace,
    productType: job.productType,
    skus: job.skus,
    startedAt: job.startedAt,
  })
  void runPreviewJob(job).catch((err) => {
    job.status = 'failed'
    job.fatalError = err instanceof Error ? err.message : String(err)
    job.doneAt = new Date().toISOString()
    void persistPullJobFinal('AMAZON', {
      jobId: job.jobId,
      status: 'failed',
      progress: job.progress, total: job.total,
      pulled: job.pulled, skipped: job.skipped, failed: job.failed,
      errors: job.errors, rows: [],
      doneAt: job.doneAt,
      fatalError: job.fatalError,
    })
  })
  return jobId
}

export function getPullPreviewJobStatus(jobId: string): PullPreviewJob | null {
  return jobs.get(jobId) ?? null
}

async function runPreviewJob(job: PullPreviewJob): Promise<void> {
  const mp = job.marketplace
  const pt = job.productType
  const marketplaceId = MARKETPLACE_ID_MAP[mp] ?? MARKETPLACE_ID_MAP.IT

  const where: Record<string, any> = { deletedAt: null, productType: pt }
  if (job.skus) where.sku = { in: job.skus }

  const products = await prisma.product.findMany({
    where,
    select: {
      id: true,
      sku: true,
      name: true,
      productType: true,
      isParent: true,
      parentId: true,
    },
    orderBy: [{ isParent: 'desc' }, { sku: 'asc' }],
    take: 2000,
  })

  job.total = products.length

  if (!products.length) {
    job.status = 'done'
    job.doneAt = new Date().toISOString()
    void persistPullJobFinal('AMAZON', {
      jobId: job.jobId,
      status: 'done',
      progress: job.progress, total: job.total,
      pulled: job.pulled, skipped: job.skipped, failed: job.failed,
      errors: job.errors, rows: job.rows,
      doneAt: job.doneAt,
    })
    return
  }

  const idToSku = new Map(products.map((p) => [p.id, p.sku]))
  const amazonService = new AmazonService()

  const pulledBySku = new Map<
    string,
    {
      asin: string | null
      attrs: Record<string, any>
      title: string | null
      listingStatus: string | null
    }
  >()

  for (const product of products) {
    try {
      const listing = await amazonService.fetchListingForFlatFile(product.sku, marketplaceId)
      if (!listing) {
        job.skipped++
        job.progress++
        continue
      }
      pulledBySku.set(product.sku, {
        asin: listing.asin,
        attrs: listing.attributes,
        title: listing.title,
        listingStatus: listing.listingStatus,
      })
      job.pulled++
    } catch (err: any) {
      job.failed++
      job.errors.push({ sku: product.sku, error: err?.message ?? 'Pull failed' })
    }
    job.progress++
  }

  // Row expansion. Mirrors the transformation block in
  // flat-file.service.ts → getExistingRows (the part after the DB query).
  // Duplicated here on purpose so the DB-writing path stays untouched.
  const INFRA = new Set(['marketplace_id', 'language_tag', 'audience'])

  job.rows = products
    .filter((p) => pulledBySku.has(p.sku))
    .map((p) => {
      const pulled = pulledBySku.get(p.sku)!
      const attrs = pulled.attrs
      const bullets: string[] = Array.isArray(attrs.bullet_point)
        ? (attrs.bullet_point as any[])
            .map((b: any) => b?.value ?? String(b))
            .filter(Boolean)
        : []

      const parentSku = p.parentId ? idToSku.get(p.parentId) ?? '' : ''

      const poAttrs = attrs.purchasable_offer?.[0] as Record<string, any> | undefined
      const poCurrency = String(poAttrs?.currency ?? CURRENCY_MAP[mp] ?? 'EUR')
      const poCondition = String(poAttrs?.condition_type ?? '')
      const poSaleAttrs = poAttrs?.sale_price?.[0] as Record<string, any> | undefined
      const poSalePrice =
        poSaleAttrs?.schedule?.[0]?.value_with_tax != null
          ? String(poSaleAttrs.schedule[0].value_with_tax)
          : ''
      const poOurPrice =
        poAttrs?.our_price?.[0]?.schedule?.[0]?.value_with_tax != null
          ? String(poAttrs.our_price[0].schedule[0].value_with_tax)
          : ''

      const faAttrs = attrs.fulfillment_availability?.[0] as Record<string, any> | undefined
      const faCode = String(faAttrs?.fulfillment_channel_code ?? 'DEFAULT')
      const faQty = faAttrs?.quantity != null ? String(faAttrs.quantity) : ''
      const faLeadTime =
        faAttrs?.lead_time_to_ship_max_days != null
          ? String(faAttrs.lead_time_to_ship_max_days)
          : ''

      const row: FlatFileRow = {
        _rowId: p.id,
        _productId: p.id,
        _isNew: false,
        _status: 'idle',
        item_sku: p.sku,
        product_type: (p.productType as string | null) ?? pt,
        record_action: 'full_update',
        parentage_level: p.isParent ? 'Parent' : p.parentId ? 'Child' : '',
        parent_sku: parentSku,
        variation_theme: String(attrs.variation_theme?.[0]?.value ?? ''),
        item_name: pulled.title ?? attrs.item_name?.[0]?.value ?? p.name ?? '',
        brand: String(attrs.brand?.[0]?.value ?? ''),
        product_description: String(attrs.product_description?.[0]?.value ?? ''),
        bullet_point: bullets[0] ?? '',
        bullet_point_2: bullets[1] ?? '',
        bullet_point_3: bullets[2] ?? '',
        bullet_point_4: bullets[3] ?? '',
        bullet_point_5: bullets[4] ?? '',
        generic_keyword: String(attrs.generic_keyword?.[0]?.value ?? ''),
        color: String(attrs.color?.[0]?.value ?? ''),
        purchasable_offer: '',
        purchasable_offer__condition_type: poCondition,
        purchasable_offer__currency: poCurrency,
        purchasable_offer__our_price: poOurPrice,
        purchasable_offer__sale_price: poSalePrice,
        purchasable_offer__sale_from_date: String(poSaleAttrs?.start_at?.[0]?.value ?? ''),
        purchasable_offer__sale_end_date: String(poSaleAttrs?.end_at?.[0]?.value ?? ''),
        fulfillment_availability: '',
        fulfillment_availability__fulfillment_channel_code: faCode,
        fulfillment_availability__quantity: faQty,
        fulfillment_availability__lead_time_to_ship_max_days: faLeadTime,
        main_product_image_locator: String(
          attrs.main_product_image_locator?.[0]?.media_location ?? '',
        ),
        _asin: pulled.asin ?? '',
        _listingStatus: pulled.listingStatus ?? '',
      }

      for (const [k, v] of Object.entries(attrs)) {
        if (k in row) continue
        if (!Array.isArray(v)) {
          if (v != null) row[k] = String(v)
          continue
        }
        if (v.length === 0) continue
        const first = v[0]
        if (typeof first !== 'object' || first === null) {
          v.forEach((item, i) => {
            if (item != null) row[`${k}_${i + 1}`] = String(item)
          })
          continue
        }
        const keys = Object.keys(first).filter((fk) => !INFRA.has(fk))
        if (keys.length === 0) continue
        if (keys.length === 1 && keys[0] === 'value') {
          if (v.length > 1) {
            v.forEach((item, i) => {
              const val = item?.value
              if (val != null) row[`${k}_${i + 1}`] = String(val)
            })
          } else {
            const val = first.value
            if (val != null) row[k] = String(val)
          }
        } else if (keys.length === 2 && keys.includes('value') && keys.includes('unit')) {
          if (first.value != null) row[`${k}__value`] = String(first.value)
          if (first.unit) row[`${k}__unit`] = String(first.unit)
        } else if (v.length > 1 && keys.includes('value')) {
          v.forEach((item, i) => {
            const val = item?.value
            if (val != null) row[`${k}_${i + 1}`] = String(val)
          })
        } else {
          for (const subKey of keys) {
            if (subKey === 'value') continue
            const subVal = first[subKey]
            if (typeof subVal === 'object' && subVal !== null) {
              if (subVal.value != null) row[`${k}__${subKey}`] = String(subVal.value)
              if (subVal.unit) row[`${k}__${subKey}_unit`] = String(subVal.unit)
            } else if (subVal != null && subVal !== '') {
              row[`${k}__${subKey}`] = String(subVal)
            }
          }
        }
      }

      return row
    })

  job.status = 'done'
  job.doneAt = new Date().toISOString()
  void persistPullJobFinal('AMAZON', {
    jobId: job.jobId,
    status: 'done',
    progress: job.progress, total: job.total,
    pulled: job.pulled, skipped: job.skipped, failed: job.failed,
    errors: job.errors, rows: job.rows,
    doneAt: job.doneAt,
  })
}

/**
 * Flat-File Pull Service
 *
 * Background job that reconciles the platform's ChannelListing records
 * against Amazon's live listing data by calling getListingsItem per SKU.
 *
 * What it writes per SKU (for the requested marketplace):
 *   ChannelListing.platformAttributes.attributes  ← raw SP-API attributes
 *   ChannelListing.title / description / bulletPointsOverride / price / qty
 *   ChannelListing.externalListingId              ← ASIN
 *   ChannelListing.listingStatus / isPublished
 *   Product.isParent / parentId                  ← from SP-API relationships
 *   ProductVariation.amazonAsin
 *
 * After all SKUs are processed, getExistingRows() is called so the client
 * receives fully-expanded flat-file rows it can write to localStorage and
 * open directly in the flat file editor.
 *
 * Job lifecycle:
 *   startPullJob()  → returns jobId immediately, work starts async
 *   getJobStatus()  → poll every 3 s; status: 'running' | 'done' | 'failed'
 *   Jobs are kept in memory for 2 hours, then pruned.
 */

import prisma from '../../db.js'
import { productEventService } from '../product-event.service.js'
import { AmazonService, AMAZON_MARKETPLACE_CODE_TO_ID } from '../marketplaces/amazon.service.js'
import { AmazonFlatFileService } from './flat-file.service.js'
import { CategorySchemaService } from '../categories/schema-sync.service.js'
import { MARKETPLACE_ID_MAP, LANGUAGE_TAG_MAP, CURRENCY_MAP } from './flat-file.service.js'

// ── Job types ──────────────────────────────────────────────────────────────

export interface PullJob {
  jobId: string
  marketplace: string
  productType: string
  status: 'running' | 'done' | 'failed'
  progress: number
  total: number
  pulled: number
  skipped: number
  failed: number
  errors: Array<{ sku: string; error: string }>
  rows: any[]
  startedAt: string
  doneAt?: string
  fatalError?: string
}

// ── In-memory store ────────────────────────────────────────────────────────

const JOB_TTL_MS = 2 * 60 * 60 * 1000 // 2 hours
const jobs = new Map<string, PullJob>()

function pruneOldJobs() {
  const cutoff = Date.now() - JOB_TTL_MS
  for (const [id, job] of jobs) {
    if (new Date(job.startedAt).getTime() < cutoff) jobs.delete(id)
  }
}

// ── Public API ─────────────────────────────────────────────────────────────

export function startPullJob(marketplace: string, productType: string): string {
  pruneOldJobs()
  const jobId = `ffpull-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
  const job: PullJob = {
    jobId,
    marketplace: marketplace.toUpperCase(),
    productType: productType.toUpperCase(),
    status: 'running',
    progress: 0,
    total: 0,
    pulled: 0,
    skipped: 0,
    failed: 0,
    errors: [],
    rows: [],
    startedAt: new Date().toISOString(),
  }
  jobs.set(jobId, job)
  void runJob(job).catch((err) => {
    job.status = 'failed'
    job.fatalError = err instanceof Error ? err.message : String(err)
    job.doneAt = new Date().toISOString()
  })
  return jobId
}

export function getJobStatus(jobId: string): PullJob | null {
  return jobs.get(jobId) ?? null
}

// ── All-markets pull ───────────────────────────────────────────────────────

export interface AllMarketsPullJob {
  jobId: string
  productType: string
  markets: string[]
  currentMarket: string | null
  status: 'running' | 'done' | 'failed'
  perMarket: Record<string, PullJob | null>
  startedAt: string
  doneAt?: string
  fatalError?: string
}

const allMarketJobs = new Map<string, AllMarketsPullJob>()

export function startAllMarketsPullJob(productType: string, markets: string[]): string {
  pruneOldJobs()
  const jobId = `ffpull-all-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
  const perMarket: Record<string, PullJob | null> = {}
  for (const mp of markets) perMarket[mp.toUpperCase()] = null

  const parentJob: AllMarketsPullJob = {
    jobId,
    productType: productType.toUpperCase(),
    markets: markets.map((m) => m.toUpperCase()),
    currentMarket: null,
    status: 'running',
    perMarket,
    startedAt: new Date().toISOString(),
  }
  allMarketJobs.set(jobId, parentJob)

  void runAllMarketsJob(parentJob).catch((err) => {
    parentJob.status = 'failed'
    parentJob.fatalError = err instanceof Error ? err.message : String(err)
    parentJob.doneAt = new Date().toISOString()
  })
  return jobId
}

export function getAllMarketsPullJobStatus(jobId: string): AllMarketsPullJob | null {
  return allMarketJobs.get(jobId) ?? null
}

async function runAllMarketsJob(parentJob: AllMarketsPullJob): Promise<void> {
  for (const mp of parentJob.markets) {
    parentJob.currentMarket = mp
    const childJob: PullJob = {
      jobId: `ffpull-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      marketplace: mp,
      productType: parentJob.productType,
      status: 'running',
      progress: 0, total: 0, pulled: 0, skipped: 0, failed: 0,
      errors: [], rows: [],
      startedAt: new Date().toISOString(),
    }
    jobs.set(childJob.jobId, childJob)
    parentJob.perMarket[mp] = childJob
    await runJob(childJob) // sequential — rate-limit friendly
  }
  parentJob.currentMarket = null
  parentJob.status = 'done'
  parentJob.doneAt = new Date().toISOString()
}

// ── Core job logic ─────────────────────────────────────────────────────────

async function runJob(job: PullJob): Promise<void> {
  const { marketplace: mp, productType: pt } = job
  const marketplaceId = MARKETPLACE_ID_MAP[mp] ?? MARKETPLACE_ID_MAP.IT
  const channelMarket = `AMAZON_${mp}`

  // All products for this productType, parents first
  const products = await prisma.product.findMany({
    where: { deletedAt: null, productType: pt },
    select: { id: true, sku: true, isParent: true, parentId: true },
    orderBy: [{ isParent: 'desc' }, { sku: 'asc' }],
    take: 2000,
  })

  job.total = products.length

  if (!products.length) {
    job.status = 'done'
    job.doneAt = new Date().toISOString()
    return
  }

  const amazonService = new AmazonService()

  // Pre-build ASIN → SKU from existing ChannelListings for this marketplace
  // so child rows can resolve their parent SKU even before the parent is pulled.
  const existingListings = await prisma.channelListing.findMany({
    where: { channel: 'AMAZON', marketplace: mp, externalListingId: { not: null } },
    select: { externalListingId: true, product: { select: { sku: true } } },
  })
  const asinToSku = new Map<string, string>(
    existingListings
      .filter((r) => r.externalListingId)
      .map((r) => [r.externalListingId!, r.product.sku]),
  )

  // Process SKUs sequentially so we build up asinToSku as parents are pulled.
  // The SP client handles rate-limit back-off automatically.
  const pulledOk: Array<{ id: string; sku: string }> = []
  for (const product of products) {
    try {
      const listing = await amazonService.fetchListingForFlatFile(product.sku, marketplaceId)

      if (!listing) {
        job.skipped++
        job.progress++
        continue
      }

      const { asin, attributes: attrs, title, listingStatus, productType: amazonPt, relationships } = listing

      // Track ASIN → SKU so subsequent child lookups can resolve
      if (asin) asinToSku.set(asin, product.sku)

      // ── Price + qty from attributes ──────────────────────────────
      let price: number | null = null
      const offerAttr = attrs.purchasable_offer
      if (Array.isArray(offerAttr) && offerAttr[0]) {
        const schedule = offerAttr[0]?.our_price?.[0]?.schedule?.[0]
        if (schedule?.value_with_tax != null) price = parseFloat(String(schedule.value_with_tax))
      }

      let qty: number | null = null
      const qtyAttr = attrs.fulfillment_availability
      if (Array.isArray(qtyAttr) && qtyAttr[0]?.quantity != null) {
        qty = parseInt(String(qtyAttr[0].quantity), 10)
      }

      // ── Parentage from relationships ─────────────────────────────
      let isParentListing = false
      let parentAsin: string | null = null

      for (const rel of relationships) {
        if (rel.type === 'VARIATION') {
          if (Array.isArray(rel.childAsins) && rel.childAsins.length > 0) {
            isParentListing = true
          }
          if (typeof rel.parentAsin === 'string') {
            parentAsin = rel.parentAsin
          }
        }
      }

      const parentSku = parentAsin ? (asinToSku.get(parentAsin) ?? null) : null

      // ── Bullet points ────────────────────────────────────────────
      const bulletsRaw = attrs.bullet_point
      const bullets: string[] = Array.isArray(bulletsRaw)
        ? bulletsRaw.map((b: any) => b?.value ?? String(b)).filter(Boolean)
        : []

      // ── Upsert ChannelListing ────────────────────────────────────
      const existingCl = await prisma.channelListing.findFirst({
        where: { productId: product.id, channel: 'AMAZON', marketplace: mp },
        select: { id: true, version: true },
      })

      const listingPayload: Record<string, any> = {
        channel: 'AMAZON',
        marketplace: mp,
        region: mp,
        channelMarket,
        title: title ?? attrs.item_name?.[0]?.value ?? undefined,
        description: attrs.product_description?.[0]?.value ?? undefined,
        platformAttributes: { attributes: attrs },
        externalListingId: asin,
        syncStatus: 'SYNCED',
        lastSyncedAt: new Date(),
        lastSyncStatus: 'SUCCESS',
        // P0 2026-07-20 — DISCOVERABLE means the listing EXISTS on Amazon
        // (incomplete offer, but live + manageable); marking it unpublished
        // made dispatch skip every push (431 blocked rows measured). Any
        // Amazon-known status is publishable.
        isPublished: ['BUYABLE', 'ACTIVE', 'DISCOVERABLE'].includes(listingStatus ?? 'ACTIVE'),
        listingStatus: listingStatus ?? 'ACTIVE',
        followMasterTitle: false,
        followMasterDescription: false,
        ...(bullets.length > 0 ? { bulletPointsOverride: bullets, followMasterBulletPoints: false } : {}),
        ...(price !== null && !isNaN(price) ? { price, followMasterPrice: false } : {}),
      }
      // P0 2026-07-20 — the pull must NEVER pin quantity. The owner lists on
      // Amazon at qty 0 (their own Excel upload) and the POOL takes over;
      // the old `{ quantity, followMasterQuantity: false }` pinned every
      // pulled listing at Amazon's momentary number (0 at birth) and froze
      // it off the pool — the exact zero-inventory incident. Observed qty
      // goes on CREATE only, as an initial value under the schema-default
      // followMasterQuantity=true (first cascade replaces it with pool
      // truth); on UPDATE the pool owns ChannelListing.quantity.
      const createOnlyQty = qty !== null && !isNaN(qty) ? { quantity: qty } : {}

      if (existingCl) {
        await prisma.channelListing.update({
          where: { id: existingCl.id },
          data: { ...listingPayload, version: { increment: 1 } },
        })
      } else {
        Object.assign(listingPayload, createOnlyQty)
        await prisma.channelListing.create({
          data: { productId: product.id, ...listingPayload } as any,
        })
      }

      // ── Product hierarchy ────────────────────────────────────────
      const productUpdates: Record<string, any> = {}
      if (isParentListing && !product.isParent) productUpdates.isParent = true
      if (amazonPt && amazonPt.toUpperCase() !== pt) {
        // Don't overwrite productType if Amazon returns something different
        // (can happen on shared-ASIN pan-EU accounts) — only set if blank
      }
      if (parentSku) {
        const parentProduct = products.find((p) => p.sku === parentSku)
        if (parentProduct && product.parentId !== parentProduct.id) {
          productUpdates.parentId = parentProduct.id
        }
      }
      if (Object.keys(productUpdates).length) {
        await prisma.product.update({ where: { id: product.id }, data: productUpdates })
      }

      // ── ASIN on ProductVariation ─────────────────────────────────
      if (asin) {
        await prisma.productVariation.updateMany({
          where: { productId: product.id },
          data: { amazonAsin: asin },
        })
      }

      job.pulled++
      pulledOk.push({ id: product.id, sku: product.sku })
    } catch (err: any) {
      job.failed++
      job.errors.push({ sku: product.sku, error: err?.message ?? 'Pull failed' })
    }

    job.progress++
  }

  // Generate flat-file rows from DB — reuses all expansion logic in getExistingRows.
  // FFT.3a — the rows are built with the snapshot overlay BYPASSED and become
  // the NEW flatFileSnapshot of every pulled listing: a pull ADOPTS Amazon
  // truth, and the old snapshot previously masked the entire pull in the grid
  // ("Pull visibly does nothing"). Non-pulled listings keep their snapshots.
  try {
    const amazon = new AmazonService()
    const schemaService = new CategorySchemaService(prisma, amazon)
    const flatFileService = new AmazonFlatFileService(prisma, schemaService)
    const freshRows = await flatFileService.getExistingRows(mp, pt, undefined, 'listed', { skipSnapshotOverlay: true })
    const rowBySku = new Map(freshRows.map((r) => [String((r as Record<string, unknown>).item_sku ?? ''), r]))
    for (const { id, sku } of pulledOk) {
      const row = rowBySku.get(sku)
      if (!row) continue
      const snap = Object.fromEntries(Object.entries(row).filter(([k]) => !k.startsWith('_')))
      await prisma.channelListing.updateMany({
        where: { productId: id, channel: 'AMAZON', marketplace: mp },
        data: { flatFileSnapshot: snap } as never,
      }).catch(() => null)
    }
    if (pulledOk.length > 0) {
      try {
        void productEventService.emitMany(pulledOk.map(({ id }) => ({
          aggregateId: id,
          aggregateType: 'Product' as const,
          eventType: 'CHANNEL_LISTING_UPDATED' as const,
          data: { channel: 'AMAZON', marketplace: mp, via: 'flat-file-pull' },
          metadata: { source: 'OPERATOR' as const },
        })) as Parameters<typeof productEventService.emitMany>[0])
      } catch { /* events are best-effort */ }
    }
    job.rows = freshRows
  } catch {
    job.rows = []
  }

  job.status = 'done'
  job.doneAt = new Date().toISOString()
}

